#include <condition_variable>
#include <cstdio>
#include <mutex>
#include <thread>

// Two threads print 1..max alternately: odd thread prints odd numbers, even thread even.
void print_alternately(int max) {
  std::mutex m;
  std::condition_variable cv;
  int next = 1;                                   // next number to print; guarded by m

  auto worker = [&](int parity) {                 // parity: 1 = odd, 0 = even
    std::unique_lock lk(m);
    for (;;) {
      cv.wait(lk, [&] { return next > max || next % 2 == parity; });
      if (next > max) return;                     // checked after wait, under the lock
      std::printf("%d\n", next);
      ++next;
      cv.notify_one();                            // exactly one other waiter exists
    }
  };
  std::thread odd(worker, 1), even(worker, 0);
  odd.join();
  even.join();
}

