class AppendList {
  std::vector<int> data;
  std::mutex m;
  std::condition_variable cv;
  int readers = 0;
  bool writing = false;
public:
  int read(size_t i) {
    std::unique_lock lk(m);
    cv.wait(lk, [&] { return !writing; });
    ++readers;
    lk.unlock();
    int v = data.at(i);          // many readers here at once
    lk.lock();
    if (--readers == 0) cv.notify_all();
    return v;
  }
  void write(int v) {
    std::unique_lock lk(m);
    cv.wait(lk, [&] { return !writing && readers == 0; });
    writing = true;
    lk.unlock();
    data.push_back(v);           // exclusive: may reallocate
    lk.lock();
    writing = false;
    cv.notify_all();
  }
};

